ALTER COLUMN project_id TYPE text;

alter table nature
ADD constraint fk_nature_project_id
foreign key (project_id) references project (id)
ON DELETE CASCADE;

alter table representation_metadata
ADD constraint fk_representation_data_project_id
foreign key (project_id) references project (id)
ON DELETE CASCADE;

alter table semantic_data
ADD constraint fk_semantic_data_project_id
foreign key (project_id) references project (id)
ON DELETE CASCADE;

alter table project_image
ADD constraint fk_project_image_project_id
foreign key (project_id) references project (id)
ON DELETE CASCADE;

ALTER TABLE representation_metadata
ALTER COLUMN id TYPE TEXT
USING CONCAT_WS('#', semantic_data_id::text, representation_metadata_id::text);

ALTER TABLE representation_metadata_icon_url
ALTER COLUMN representation_metadata_id TYPE TEXT
USING CONCAT_WS('#', semantic_data_id::text, representation_metadata_id::text);

ALTER TABLE representation_content
ALTER COLUMN id TYPE TEXT
USING CONCAT_WS('#', semantic_data_id::text, representation_metadata_id::text);
